C(26,'<label><input type="checkbox">이동</label><section>'+Array.from({length:50},(_,i)=>'<div class="card">'+(i+1)+'</div>').join('')+'</section>','section{display:flex;flex-wrap:wrap;gap:5px}.card{width:40px;height:30px;background:#8dbef5;transition:width 500ms,transform 500ms}body:has(input:checked) .card{width:60px;/* 비교: width 대신 transform:translateX(20px) */}','실제 Layout/Paint/Composite 비용은 DevTools Performance로 두 조건을 각각 기록하세요. 미리보기는 비용을 자동 추론하지 않습니다.');
C(27,'<main>'+Array.from({length:200},(_,i)=>'<article><a href="#card-'+i+'" id="card-'+i+'">카드 '+i+'</a><p>'+('높이가 다른 내용 '.repeat(i%7+1))+'</p></article>').join('')+'</main>','article{content-visibility:auto;contain-intrinsic-size:auto 120px;margin:16px;padding:20px;border:1px solid #92b9e5}','content-visibility를 visible로 바꾸고 초기 렌더 및 스크롤을 기록하세요. 검색과 Tab으로 뒤쪽 카드에 도달하는지도 확인합니다.');
function dataSource(unit,spec){return `// ${unit.title}\n// 편집할 실험 입력과 알고리즘입니다.\nexport function mount({container}) {\nconst INITIAL=${JSON.stringify(spec.input)};\nconst controller=new AbortController(),signal=controller.signal;\nconst timers=[],urls=[];let disposed=false;\nconst later=(fn,delay)=>{const id=setTimeout(fn,delay);timers.push(id);return id};\nconst title=document.createElement('h2');title.textContent=${JSON.stringify(unit.title)};\nconst help=document.createElement('p');help.textContent=${JSON.stringify(spec.note||unit.variables[0].baseline+' → '+unit.variables[0].change+' 조건으로 입력을 바꿔 실행하세요.')};\nconst editor=document.createElement('textarea');editor.value=JSON.stringify(INITIAL,null,2);editor.rows=10;editor.style.cssText='width:100%;font-family:monospace';editor.setAttribute('aria-label','실험 JSON 입력');\nconst button=document.createElement('button');button.textContent='실험 실행';\nconst output=document.createElement('pre');output.style.whiteSpace='pre-wrap';output.setAttribute('aria-live','polite');const stage=document.createElement('section');\nconst show=value=>{if(!disposed)output.textContent=typeof value==='string'?value:JSON.stringify(value,null,2)};\n/** @param {any} input */\nasync function experiment(input){${spec.body}}\nlet generation=0;const run=async()=>{const current=++generation;try{const result=await experiment(JSON.parse(editor.value));if(current===generation)show(result)}catch(error){if(current===generation)show({error:String(error)})}};\nbutton.addEventListener('click',run,{signal});container.append(title,help,editor,button,stage,output);run();\nreturn ()=>{disposed=true;controller.abort();timers.forEach(clearTimeout);urls.forEach(url=>URL.revokeObjectURL(url));container.replaceChildren()};\n}\n`}

const responsiveSources=[300,600,1200].map(width=>({width,url:'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="'+width+'" height="'+(width/2)+'"><rect width="100%" height="100%" fill="'+(width===300?'coral':width===600?'steelblue':'seagreen')+'"/><text x="20" y="60" font-size="40" fill="white">'+width+'w</text></svg>')}));
specs.html[19]={html:'<img src="'+responsiveSources[1].url+'" srcset="'+responsiveSources.map(s=>s.url+' '+s.width+'w').join(', ')+'" sizes="(max-width:600px) 100vw, 600px" width="600" height="300" alt="선택된 후보의 너비와 색"><p>검사에서 currentSrc를 확인하세요.</p>',css:'img{max-width:100%;height:auto}',note:'300/600/1200w SVG 후보가 실제 srcset으로 선택됩니다. sizes와 DPR 및 미리보기 viewport가 선택에 영향을 줍니다. data URL은 네트워크 전송량 비교용이 아닙니다.'};

for(const series of Object.keys(specs)){
const units=JSON.parse(fs.readFileSync('content/curricula/'+series+'.json','utf8')).units.filter(u=>u.id.includes('-step-'));
const metadata={};for(const unit of units){const spec=specs[series][unit.day];if(!spec)throw new Error('Missing '+unit.id);if(!/^(javascript|typescript|html|css)-step-\d{2}$/.test(unit.id))throw new Error('Unexpected unit '+unit.id);const dir='src/labs/'+unit.id;fs.mkdirSync(dir,{recursive:true});const file=dir+'/example.js';fs.writeFileSync(file,series==='html'||series==='css'?documentSource(unit,spec):dataSource(unit,spec));if(spec.source)fs.writeFileSync(dir+'/lesson.ts',spec.source);metadata[unit.id]={mode:series==='html'&&[18,21,23].includes(unit.day)?'external':'browser',note:spec.note||(series==='css'?'실제 CSS 문서를 렌더하고 DOM 치수와 계산 스타일을 검사합니다.':'편집 가능한 입력과 실제 브라우저 실행 결과를 비교합니다.'),...(spec.source?{files:[dir+'/example.js',dir+'/lesson.ts']}: {})};}
if(series==='html'||series==='css')for(const item of Object.values(metadata))item.note+=' Shadow DOM에서 문서 body/html 선택자를 범위화합니다. @media는 외부 미리보기 viewport에 반응하며 폭 슬라이더는 컨테이너만 변경합니다. 네트워크·폼 이동·iframe 실행은 제한됩니다.';
fs.mkdirSync('content/examples',{recursive:true});fs.writeFileSync('content/examples/'+series+'.json',JSON.stringify(metadata,null,2)+'\n');console.log(series,units.length);
}
function documentSource(unit,spec){return `// ${unit.title}: 실제 HTML/CSS 실험
export function mount({container}) {
const HTML=${JSON.stringify(spec.html)},CSS=${JSON.stringify(spec.css||'')};
const originalRootSize=document.documentElement.style.fontSize;
const controller=new AbortController(),signal=controller.signal;
const heading=document.createElement('h2');heading.textContent=${JSON.stringify(unit.title)};
const note=document.createElement('p');note.textContent=${JSON.stringify((spec.note||unit.variables[0].baseline+' → '+unit.variables[0].change+'를 비교하세요.')+' Shadow DOM에서 body/html/:root를 .doc로 옮깁니다. @media는 바깥 미리보기 viewport에 반응합니다. 폭 슬라이더는 컨테이너 폭만 변경합니다. 네트워크·폼 이동·iframe은 제한됩니다.')};
const html=document.createElement('textarea'),css=document.createElement('textarea');html.value=HTML;css.value=CSS;
for(const field of [html,css]){field.setAttribute('aria-label',field===html?'HTML 소스':'CSS 소스');field.rows=6;field.style.cssText='display:block;width:100%;font-family:monospace'}
const apply=document.createElement('button');apply.textContent='적용';const inspect=document.createElement('button');inspect.textContent='현재 DOM / 스타일 검사';
const width=document.createElement('input');width.type='range';width.min='280';width.max='1200';width.value='700';width.setAttribute('aria-label','컨테이너 폭');
const host=document.createElement('section');host.style.cssText='display:block;background:white;border:1px solid #9ab;max-width:100%;max-height:450px;overflow:auto';const shadow=host.attachShadow({mode:'open'});
const output=document.createElement('pre');output.style.whiteSpace='pre-wrap';output.setAttribute('aria-live','polite');let sourceDocument;
const measure=()=>{const root=shadow.querySelector('.doc');if(!root)return;const nodes=[...root.querySelectorAll('.card,.child,button,img,input,article,p')].slice(0,18);output.textContent=JSON.stringify({title:sourceDocument.title,lang:sourceDocument.documentElement.lang,containerWidth:host.clientWidth,viewportWidth:innerWidth,scrollWidth:root.scrollWidth,forms:[...root.querySelectorAll('form')].map(form=>({valid:form.checkValidity(),entries:[...new FormData(form)]})),links:[...root.querySelectorAll('a')].slice(0,8).map(a=>({text:a.textContent,href:a.getAttribute('href')})),nodes:nodes.map(node=>{const s=getComputedStyle(node);return {tag:node.tagName,width:Math.round(node.getBoundingClientRect().width),color:s.color,background:s.backgroundColor,display:s.display,boxSizing:s.boxSizing,grid:s.gridTemplateColumns,transform:s.transform,currentSrc:node instanceof HTMLImageElement?node.currentSrc:undefined}}),repairedBody:root.innerHTML.slice(0,1800)},null,2)};
const render=()=>{if(${JSON.stringify(unit.id==='css-step-05')}){const font=css.value.match(/font-size:[ ]*([0-9.]+px)/);if(font)document.documentElement.style.fontSize=font[1]}sourceDocument=new DOMParser().parseFromString(html.value,'text/html');const style=document.createElement('style');style.textContent='.doc{font-family:system-ui;color:#172c43;padding:16px}'+css.value.replace(/:root|\\bbody\\b|\\bhtml\\b/g,'.doc');const root=document.createElement('div');root.className='doc';root.lang=sourceDocument.documentElement.lang;root.innerHTML=sourceDocument.body.innerHTML;root.querySelectorAll('script,iframe').forEach(node=>{const text=document.createElement('pre');text.textContent='외부 환경에서 실행할 요소: '+node.outerHTML;node.replaceWith(text)});shadow.replaceChildren(style,root);host.style.width=width.value+'px';root.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const dialog=form.closest('dialog');if(form.getAttribute('method')==='dialog')dialog?.close();measure()},{signal}));root.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',event=>{event.preventDefault();const id=a.getAttribute('href').slice(1);const target=[...root.querySelectorAll('[id]')].find(node=>node.id===id);target?.scrollIntoView();if(target instanceof HTMLElement)target.focus()},{signal}));const opener=root.querySelector('[data-open-dialog]'),dialog=root.querySelector('dialog');opener?.addEventListener('click',()=>dialog?.showModal(),{signal});const template=root.querySelector('template'),target=root.querySelector('[data-cards]');if(template&&target){for(let i=0;i<3;i++){const fragment=/** @type {DocumentFragment} */(template.content.cloneNode(true));const input=fragment.querySelector('input'),label=fragment.querySelector('label');if(input)input.id='title-'+i;if(label)label.htmlFor='title-'+i;target.append(fragment)}}measure()};
apply.addEventListener('click',render,{signal});inspect.addEventListener('click',measure,{signal});width.addEventListener('input',()=>{host.style.width=width.value+'px';measure()},{signal});container.append(heading,note,html,css,apply,inspect,width,host,output);render();
return ()=>{controller.abort();document.documentElement.style.fontSize=originalRootSize;shadow.replaceChildren();container.replaceChildren()};
}
`}
